SELECT SUM(c.population) AS total_pop
FROM country c
WHERE NOT EXISTS (
  SELECT 1 FROM countrylanguage cl
  WHERE cl.countrycode = c.code AND cl.language = 'English'
);

queries.sql:
SELECT COUNT(*) AS n_countries, SUM(population) AS total_pop
FROM country c
WHERE NOT EXISTS (
  SELECT 1 FROM countrylanguage cl
  WHERE cl.countrycode = c.code AND cl.language = 'English'
);
